// randomHalves returns nbInstances random instances as the columns Assignment takes.
func randomHalves(width, nbInstances int) (left, right [][]mamabear.Element) {
	columns := func() [][]mamabear.Element {
		res := make([][]mamabear.Element, width/2)
		for i := range res {
			res[i] = make([]mamabear.Element, nbInstances)
			mamabear.Vector(res[i]).MustSetRandom()
		}
		return res
	}
	return columns(), columns()
}

// newHasher returns a hasher for the gadget's proofs.
func newHasher() *extensionsHash.BaseFieldHashAdapterE3 {
	return extensionsHash.NewBaseFieldHashAdapterE3(poseidon2.NewMerkleDamgardHasher())
}

