// TestCompressor proves and verifies 2⁶ random instances with the default parameters, and checks
// the circuit's outputs against gnark-crypto's compression function.
func TestCompressor(t *testing.T) {
	const logNbInstances = 6

	params := poseidon2.GetDefaultParameters()
	compressor, err := NewCompressor(params)
	require.NoError(t, err)

	left, right := randomHalves(params.Width, 1<<logNbInstances)
	assignment := compressor.Assignment(left, right)

	proof, proverClaims, err := gkrmamabear.Prove(compressor.Circuit, compressor.Schedule, assignment, newHasher())
	require.NoError(t, err)
	require.NoError(t, proverClaims.Check(assignment))

	// Prove has computed the outputs.
	reference := poseidon2.NewCompressor(poseidon2.NewDefaultPermutation())
	half := params.Width / 2
	leftRow := make([]mamabear.Element, half)
	rightRow := make([]mamabear.Element, half)
	expected := make([]mamabear.Element, half)
	for instanceI := range 1 << logNbInstances {
		for i := range half {
			leftRow[i] = left[i][instanceI]
			rightRow[i] = right[i][instanceI]
		}
		reference.CompressField(expected, leftRow, rightRow)
		for i := range half {
			assert.True(t, expected[i].Equal(&assignment[compressor.Out[i]][instanceI]), "instance %d, output %d", instanceI, i)
		}
	}

	verifierClaims, err := gkrmamabear.Verify(compressor.Circuit, compressor.Schedule, logNbInstances, proof, newHasher())
	require.NoError(t, err)
	require.NoError(t, verifierClaims.Check(assignment))
}

func BenchmarkCompressor(b *testing.B) {
	const nbInstances = 1 << 16

	params := poseidon2.GetDefaultParameters()
	compressor, err := NewCompressor(params)
	require.NoError(b, err)

	left, right := randomHalves(params.Width, nbInstances)

	b.ResetTimer()
	for range b.N {
		_, _, err = gkrmamabear.Prove(compressor.Circuit, compressor.Schedule, compressor.Assignment(left, right), newHasher())
		require.NoError(b, err)
	}
}
